  // شجرة الوثيق: البنية الهرمية والواجهة، على نفس حسابات وقيود الميزان دون ترحيل أو استبدال بيانات.
  const w30Groups = [['1','الأصول','asset',''],['11','الأصول المتداولة','asset','1'],['111','النقدية وما في حكمها','asset','11'],['1111','الصناديق والمحافظ','asset','111'],['1112','البنوك','asset','111'],['112','ذمم العملاء والمدينون','asset','11'],['113','المخزون','asset','11'],['114','مصروفات مقدمة وإيرادات مستحقة وأرصدة أخرى','asset','11'],['12','الأصول غير المتداولة','asset','1'],['121','العقارات والأراضي والمباني','asset','12'],['122','السيارات ووسائل النقل','asset','12'],['123','الأجهزة والمعدات والآلات','asset','12'],['124','مجمع الإهلاك','asset','12'],['2','الالتزامات','liability',''],['21','الالتزامات المتداولة','liability','2'],['211','ذمم الموردين والدائنون','liability','21'],['212','القروض قصيرة الأجل والسحب على المكشوف','liability','21'],['213','المصروفات المستحقة والإيرادات المقدمة','liability','21'],['214','الضرائب المستحقة','liability','21'],['22','الالتزامات غير المتداولة','liability','2'],['221','القروض والتمويلات طويلة الأجل','liability','22'],['3','حقوق الملكية','equity',''],['31','رأس المال والأرصدة الافتتاحية','equity','3'],['32','جاري الشركاء والمسحوبات','equity','3'],['33','الأرباح والخسائر المبقاة','equity','3'],['34','الاحتياطيات','equity','3'],['4','الإيرادات','revenue',''],['41','الإيرادات التشغيلية','revenue','4'],['42','مردودات ومسموحات المبيعات والخصم المسموح','revenue','4'],['43','الإيرادات الأخرى','revenue','4'],['5','المصروفات','expense',''],['51','تكلفة المبيعات','expense','5'],['52','المصروفات الإدارية والعمومية','expense','5'],['53','مصروفات البيع والتسويق','expense','5'],['54','المصروفات المالية والتشغيلية الأخرى','expense','5']];
