    for(const [code,name,type,parent] of w30Groups){const n={id:'g:'+code,code,name,type,parent:parent?'g:'+parent:'',group:true,normal:code==='124'?'credit':['32','42'].includes(code)||['asset','expense'].includes(type)?'debit':'credit',debit:0,credit:0,children:[]};nodes.push(n);ids.set(n.id,n);used.add(code)}
