  function triggerPrintOnce(hash,view){
    if(!hash.startsWith('print-invoice/')){requestAnimationFrame(()=>setTimeout(()=>window.print(),90));return}
    const id=hash.split('/')[1]||'',params=new URLSearchParams(location.search),token=params.get('printToken')||`direct-${id}-${Math.round(performance.timeOrigin||Date.now())}`,key=`almezan_invoice_printed::${token}`;
    if(window.__almezanInvoicePrintStarted)return;
    try{if(sessionStorage.getItem(key)==='1')return;sessionStorage.setItem(key,'1')}catch(_){ }
    window.__almezanInvoicePrintStarted=true;
    const fire=()=>requestAnimationFrame(()=>setTimeout(()=>{try{window.print()}catch(e){console.error(e)}},120));
    const imgs=Array.from(view.querySelectorAll('img'));if(!imgs.length){fire()}else Promise.allSettled(imgs.map(img=>img.complete?Promise.resolve():img.decode?.()||new Promise(r=>{img.onload=img.onerror=r}))).then(fire);
    if(window.opener&&!window.opener.closed&&!window.__almezanAfterPrintCloseBound){window.__almezanAfterPrintCloseBound=true;window.addEventListener('afterprint',()=>setTimeout(()=>{try{window.close()}catch(_){}},120),{once:true})}
  }
  function renderPrint(hash){
    $('#loginScreen').hidden=true;$('#appShell').hidden=true;let view=$('.print-view');if(!view){view=document.createElement('div');view.className='print-view';document.body.appendChild(view)}document.body.classList.add('printing');ensureInvoicePrintStyles();let html='';
    if(hash.startsWith('print-invoice/')){const id=hash.split('/')[1],x=D().sales.find(s=>s.id===id);html=x?invoiceReceiptHtml(x):'<p>الفاتورة غير موجودة.</p>'}
    else if(hash==='print-report'){let r;try{r=JSON.parse(localStorage.getItem('almezan_report_print'))}catch(e){}if(r)html=`<section class="print-sheet"><header class="print-header"><div class="print-brand print-brand-small"><img src="${esc(A.systemLogoSrc?.()||'brand-logo.png')}" alt="شعار المحل"></div><div><h2>${esc(D().company.name)}</h2><small>${esc(D().company.legalName||'')}</small><br><small>${esc(D().company.taxNumber||'')} ${esc(D().company.phone||'')}</small></div><div class="print-title"><h3>${esc(r.title)}</h3><small>${esc(r.from)} — ${esc(r.to)}</small></div></header><table class="print-table" style="margin-top:18px"><thead><tr>${r.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr>${row.map(c=>`<td>${typeof c==='number'?A.money(c):esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="print-totals"><div class="grand"><span>الملخص</span><b>${esc(r.summary)}</b></div></div><footer class="print-footer">طبع بتاريخ ${A.dateFmt(A.now(),true)}</footer></section>`}
    else if(hash==='print-record'){let r;try{r=JSON.parse(localStorage.getItem('almezan_record_print'))}catch(e){}if(r)html=`<section class="print-sheet"><header class="print-header"><div class="print-brand print-brand-small"><img src="${esc(A.systemLogoSrc?.()||'brand-logo.png')}" alt="شعار المحل"></div><div class="print-company-block"><h2>${esc(r.company?.name||D().company.name)}</h2><p>${esc(r.company?.legalName||D().company.legalName||'')}</p><small>${esc(r.company?.phone||D().company.phone||'')} ${esc(r.company?.address||D().company.address||'')}</small><br><small>الرقم الضريبي: ${esc(r.company?.taxNumber||D().company.taxNumber||'—')}</small></div><div class="print-title"><b>تقرير سجل</b><h3>${esc(r.title||'سجل')}</h3></div></header><table class="print-table" style="margin-top:18px"><thead><tr>${(r.headers||[]).map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody><tr>${(r.values||[]).map(v=>`<td>${esc(v)}</td>`).join('')}</tr></tbody></table><footer class="print-footer">${esc(D().company.name)} — طبع بتاريخ ${A.dateFmt(A.now(),true)}</footer></section>`}
    else if(hash==='print-barcodes'){let p;try{p=JSON.parse(localStorage.getItem('almezan_barcode_print'))}catch(e){}if(p){const b=makeBarcode(p.code,p.format);html=`<section class="print-sheet"><div class="barcode-sheet">${Array.from({length:p.copies},()=>`<div class="barcode-label">${b.svg}<strong>${esc(p.label)}</strong></div>`).join('')}</div></section>`;document.body.classList.add('barcode-print')}}
    view.innerHTML=html||'<p>لا توجد بيانات للطباعة.</p>';triggerPrintOnce(hash,view)
  }

